package hk.jimmy.wearmemory;
import android.app.*; import android.content.*; import android.os.*; import android.graphics.Color; import android.view.*; import android.widget.*; import java.io.*; import java.text.*; import java.util.*;
import com.google.android.gms.wearable.*;
public class SyncService extends WearableListenerService {public void onDataChanged(DataEventBuffer events){for(DataEvent e:events)if(e.getType()==DataEvent.TYPE_CHANGED){android.net.Uri uri=e.getDataItem().getUri();String name=uri.getLastPathSegment();if(name==null||!name.matches("[0-9]+[.]pcm"))continue;try{DataMap m=DataMapItem.fromDataItem(e.getDataItem()).getDataMap();Asset a=m.getAsset("audio");File dst=new File(Ui.dir(this,"audio"),name),tmp=new File(dst+".part");try(InputStream in=com.google.android.gms.tasks.Tasks.await(Wearable.getDataClient(this).getFdForAsset(a)).getInputStream();FileOutputStream out=new FileOutputStream(tmp)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);out.getFD().sync();}if(!tmp.renameTo(dst))throw new IOException("Save failed");com.google.android.gms.tasks.Tasks.await(Wearable.getDataClient(this).deleteDataItems(uri));}catch(Exception ex){Ui.notify(this,12,"錄音同步未完成",ex.getMessage());}}}}
